from pathlib import Path
import json,html,hashlib
root=Path(__file__).resolve().parents[2];out=root/'output/validation/embedding-comparison'
data=json.loads((out/'dataset.json').read_text());passages={p['id']:p['text'] for p in data['passages']}
results=[json.loads((out/f'{name}.json').read_text()) for name in ['qwen','e5','bge','gemma']]
names={'qwen':'Qwen3-Embedding-0.6B Q8','e5':'multilingual-e5-small','bge':'BGE-M3 (dense)','gemma':'EmbeddingGemma-300m'}
assert all(r['questions']==40 and r['passages']==168 and r['dataset_sha256']==hashlib.sha256((out/'dataset.json').read_bytes()).hexdigest() for r in results)
for r in results:
 assert all(set(q['gold']).issubset(passages) and len(q['top4'])==4 for q in r['results'])
rows=''.join(f"<tr><th>{names[r['model']]}</th><td>{sum(q['all_at4'] for q in r['results'])}/40</td><td>{r['mrr']:.3f}</td><td>{r['index_seconds']:.2f}초</td><td>{r['query_p50_ms']:.1f}ms</td><td>{r['query_p95_ms']:.1f}ms</td><td>{r['peak_process_rss_mib']:.0f}MiB</td><td>{r['model_files_mib']:.0f}MiB</td></tr>" for r in results)
summary=' · '.join(f"{names[r['model']]} {sum(q['all_at4'] for q in r['results'])}/40" for r in results)
details=[]
for r in results:
 for q in r['results']:
  if q['all_at4']:continue
  details.append(f"<article><h3>{names[r['model']]} · {html.escape(q['query'])}</h3><p>정답 근거 순위: {q['gold_ranks']}</p><h4>정답 원문</h4>"+''.join(f'<blockquote>{html.escape(passages[g])}</blockquote>' for g in q['gold'])+'<h4>실제 상위 4개</h4><ol>'+''.join(f'<li>{html.escape(passages[g])}</li>' for g in q['top4'])+'</ol></article>')
allqs=''.join('<details><summary>'+html.escape(q['query'])+'</summary>'+''.join(f'<blockquote>{html.escape(passages[g])}</blockquote>' for g in q['gold'])+'</details>' for q in data['queries'])
body=f'''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Story Guard 로컬 임베딩 실측</title><style>body{{background:#F7F5EF;color:#252A27;font:16px/1.7 system-ui,sans-serif;margin:0}}main{{max-width:1200px;margin:auto;padding:48px 24px}}h1{{font-size:32px}}h2{{margin-top:40px}}article,section{{background:#FFFDF8;padding:24px;border:1px solid #DADFD8;border-radius:8px;margin:20px 0}}table{{border-collapse:collapse;width:100%;white-space:nowrap}}td,th{{padding:14px;text-align:left;border-bottom:1px solid #DADFD8}}th{{color:#24635B}}.scroll{{overflow:auto}}blockquote{{border-left:3px solid #24635B;padding:12px;margin:12px 0;background:#E6EFEB}}summary{{cursor:pointer;padding:12px}}a{{color:#24635B}}.muted{{color:#626B65}}</style><main><p class="muted">Story Guard · 2026-09-10 · 실제 로컬 실행 / GPT 호출 0회</p><h1>어떤 임베딩 모델이 원문 근거를 잘 찾는가?</h1><p><a href="../embedding-advanced/index.html">50회차 심화 검사 및 원고 변경 반영 결과 →</a></p><p>고정된 합성 한국어 원고 168개 구간 · 질문 40개 · CPU 4스레드 · 한 번의 측정 실행</p><section><h2>핵심 결과</h2><p>{summary}. 점수와 CPU 실행 비용을 함께 비교하며, 이 소규모 시험만으로 기본 모델을 교체하지 않는다.</p><div class="scroll"><table><thead><tr><th>모델</th><th>근거 전부 Top4</th><th>MRR</th><th>168구간 임베딩</th><th>검색 중앙값</th><th>검색 P95</th><th>프로세스 최대 RSS</th><th>모델 파일</th></tr></thead><tbody>{rows}</tbody></table></div></section><h2>해석할 때 지켜야 할 경계</h2><ul><li>Qwen은 GGUF Q8/llama.cpp, E5·BGE·EmbeddingGemma는 원본 가중치/FP32 PyTorch다. 순수 모델 구조만의 우열이 아니라 이 실행 조합의 비교다.</li><li>모든 연산은 CPU로 제한했다. 실제 Mac의 Metal/MPS 사용 시 속도는 달라진다.</li><li>EmbeddingGemma는 공식 query/document 접두사, 평균 풀링, 두 Dense 층, 정규화를 포함한 Sentence Transformers 구성을 사용했다. 768차원을 유지했다.</li><li>BGE는 dense 검색만 평가했다. sparse·multi-vector·재순위화는 포함하지 않았다.</li><li>짧은 합성 구간과 120개 반복적 방해 구간이다. 실제 장편 원고, 긴 청킹, 작가 문체 다양성을 대표하지 않는다.</li><li>서술된 회차 간격만 존재한다. 49개 완성 회차를 읽은 장거리 문맥 시험이 아니다.</li><li>질문별 첫 실행 시간을 모은 중앙값/P95이며 반복 실행 안정성이나 신뢰구간을 측정하지 않았다. 모델 로딩 시간은 파일 캐시 영향을 받는다.</li><li>근거 전부 Top4는 두 근거가 필요한 질문에서 모두 검색되어야 성공이다. MRR은 첫 정답의 역순위 평균이다. 어느 지표도 GPT의 최종 판단 정확도를 의미하지 않는다.</li><li>최대 RSS는 인터프리터·런타임을 포함한 프로세스 메모리다. 모델 파일 용량은 앱 설치 총용량과 다르다.</li><li>공통 데이터셋 SHA256: {results[0]['dataset_sha256']}</li></ul><h2>실패 문항의 원문과 검색 결과</h2>{''.join(details)}<h2>고정한 질문 40개와 정답</h2>{allqs}<h2>공식 출처</h2><p><a href="https://huggingface.co/Qwen/Qwen3-Embedding-0.6B-GGUF">Qwen GGUF</a> · <a href="https://huggingface.co/intfloat/multilingual-e5-small">E5</a> · <a href="https://huggingface.co/BAAI/bge-m3">BGE-M3</a> · <a href="https://huggingface.co/google/embeddinggemma-300m">EmbeddingGemma 공식 모델</a></p></main></html>'''
(out/'index.html').write_text(body)
md=['# 로컬 임베딩 모델 비교','', '상세 HTML: `output/validation/embedding-comparison/index.html`','', '| 모델 | 근거 전부 Top4 | MRR | 임베딩(168구간) | 검색 중앙값 | 최대 RSS |','|---|---:|---:|---:|---:|---:|']
for r in results:md.append(f"| {names[r['model']]} | {sum(q['all_at4'] for q in r['results'])}/40 | {r['mrr']:.3f} | {r['index_seconds']:.2f}초 | {r['query_p50_ms']:.1f}ms | {r['peak_process_rss_mib']:.0f}MiB |")
md+=['','EmbeddingGemma는 사용자 이용 조건 동의 및 로컬 계정 인증 후 실제 측정을 완료했다.','', 'CPU 4스레드, Qwen Q8 GGUF/llama.cpp와 E5·BGE·EmbeddingGemma FP32/PyTorch 실행 조합 비교다. GPU 성능·순수 아키텍처 우열·장편 소설 분석 정확도를 주장하지 않는다. BGE는 dense만 사용했다.','', '합성 짧은 구간 168개(120개 반복 방해 구간), 질문 40개, 단일 실행이다. 작은 자체 제작 시험이므로 결과를 일반화할 수 없다.','', '평가 데이터는 모델 결과 확인 전 생성하고 SHA256으로 고정했다. 각 JSON에 문항별 검색 순위, 입력 최대 토큰 수, 실제 실행 시간, 메모리와 실행환경이 있다. 입력을 잘라내지 않았다.','', 'E5는 query:/passage: 접두사와 masked mean pooling, BGE는 접두사 없이 CLS pooling, Qwen은 현재 앱 지시문과 last-token pooling을 사용했다. EmbeddingGemma는 공식 query/document 접두사, mean pooling, 두 Dense 층, 정규화 및 768차원을 사용했다.','', '기본 모델은 아직 교체하지 않았다. Qwen은 이번 시험의 근거 완전 검색률이 가장 높고, E5는 CPU 속도가 가장 빠르다. EmbeddingGemma는 39/40과 약 96ms로 후속 비교 후보지만 원본 모델 용량이 약 1.2GiB다. 놓친 규칙을 보완하는 검색 전략과 독립 장편 원고 평가가 선행되어야 한다.','', '재현: 각 모델을 별도 프로세스로 순차 실행한다. Qwen은 `.venv/bin/python -m scripts.embedding_benchmark.run qwen`, E5/BGE는 `.cache/embedding-bench-venv/bin/python -m scripts.embedding_benchmark.run e5` 또는 `bge`, `gemma`. 보고서: `.venv/bin/python scripts/embedding_benchmark/report.py`. 모델 다운로드 revision은 `.cache/embedding-bench-models/manifest.json`, 런타임 패키지는 `output/validation/embedding-comparison/runtime-lock.txt`, Gemma 추가 환경은 `runtime-lock-gemma.txt`에 기록했다.']
(root/'docs/embedding-model-comparison.md').write_text('\n'.join(md)+'\n')
print('Reports generated; fixed dataset and all model results validated.')
